// Normalise NIP numbers coming from the spreadsheet and validate the checksum.
// A malformed NIP is rejected locally, so we never waste an API call on it.
const cfg = $('Set API and Columns').first().json;
const column = cfg.nipColumn || 'NIP';

function checksumOk(nip) {
  if (!/^\d{10}$/.test(nip)) return false;
  const w = [6, 5, 7, 2, 3, 4, 5, 6, 7];
  const sum = w.reduce((acc, weight, i) => acc + weight * Number(nip[i]), 0);
  return sum % 11 === Number(nip[9]);
}

const out = [];
for (const item of $input.all()) {
  const row = item.json;
  const raw = String(row[column] ?? '').replace(/[^0-9]/g, '');
  out.push({
    json: {
      ...row,
      nip: raw,
      nip_valid_format: checksumOk(raw),
      row_number: row.row_number ?? null,
    },
  });
}
return out;

// Turn the Ministry of Finance response into a plain verdict.
// The API answers with { result: { subject: {...} } } — an ACTIVE taxpayer has
// statusVat = "Czynny". Anything else means: do not pay yet.
const cfg = $('Set API and Columns').first().json;
const inputs = $('Normalize and Validate NIPs').all().map(i => i.json);
const results = $input.all().map(i => i.json);

const rows = [];
for (let i = 0; i < inputs.length; i++) {
  const src = inputs[i];
  const res = results[i] || {};
  const subject = res?.result?.subject || null;

  let verdict, detail;
  if (!src.nip_valid_format) {
    verdict = 'INVALID_NIP';
    detail = 'Checksum failed — the number is not a valid Polish NIP.';
  } else if (!subject) {
    verdict = 'NOT_FOUND';
    detail = 'No taxpayer found for this NIP on the given date.';
  } else if (subject.statusVat === 'Czynny') {
    verdict = 'ACTIVE';
    detail = subject.name || '';
  } else {
    verdict = 'NOT_ACTIVE';
    detail = `statusVat = ${subject.statusVat || 'unknown'}`;
  }

  const accounts = Array.isArray(subject?.accountNumbers) ? subject.accountNumbers : [];
  const expected = String(src[cfg.accountColumn || 'Bank account'] || '').replace(/[^0-9]/g, '');
  const accountOk = !expected ? null : accounts.some(a => String(a).replace(/[^0-9]/g, '') === expected);

  rows.push({ json: {
    nip: src.nip,
    company: subject?.name || src[cfg.nameColumn || 'Company'] || '',
    verdict,
    detail,
    account_on_white_list: accountOk,
    registration_legal_date: subject?.registrationLegalDate || null,
    checked_at: new Date().toISOString(),
    row_number: src.row_number,
  }});
}

const problems = rows.filter(r => r.json.verdict !== 'ACTIVE' || r.json.account_on_white_list === false);
if (problems.length) {
  rows.unshift({ json: {
    summary: true,
    checked: rows.length,
    problems: problems.length,
    message: `${problems.length} of ${rows.length} contractors need attention before payment.`,
  }});
}
return rows;
